import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> [side, price, qty, seq]
    seq_counter = 0

    def clean(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            if oid not in book:
                heapq.heappop(heap)
            else:
                break

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
            while remaining > 0:
                clean(opp_heap)
                if not opp_heap:
                    break
                p, s, oid2 = opp_heap[0]
                if typ != 'market' and price < p:
                    break
                info = book[oid2]
                trade_qty = min(remaining, info[2])
                trades.append([oid, oid2, p, trade_qty])
                remaining -= trade_qty
                info[2] -= trade_qty
                if info[2] == 0:
                    del book[oid2]
                    heapq.heappop(opp_heap)
        else:
            opp_heap = buy_heap
            while remaining > 0:
                clean(opp_heap)
                if not opp_heap:
                    break
                negp, s, oid2 = opp_heap[0]
                p = -negp
                if typ != 'market' and price > p:
                    break
                info = book[oid2]
                trade_qty = min(remaining, info[2])
                trades.append([oid2, oid, p, trade_qty])
                remaining -= trade_qty
                info[2] -= trade_qty
                if info[2] == 0:
                    del book[oid2]
                    heapq.heappop(opp_heap)

        if typ == 'limit' and remaining > 0:
            book[oid] = [side, price, remaining, seq_counter]
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))
            seq_counter += 1
        # for ioc/market, discard remainder, nothing to do

    return trades

